import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter pw = new PrintWriter(System.out);
        AntiPalindrome solver = new AntiPalindrome();
        solver.solve(1, br, pw);
        pw.close();
    }

    static class AntiPalindrome {
        public void solve(int testNumber, BufferedReader br, PrintWriter pw) throws IOException {
            int N = Integer.parseInt(br.readLine());
            int[] cnt = new int[26];
            int move = 0;
            char[] str = br.readLine().toCharArray();
            String[] bStr = br.readLine().split(" ");
            int[] b = new int[N];
            int res = 0;
            for (int i = 0; i < N; i++) {
                b[i] = Integer.parseInt(bStr[i]);
                res += b[i];
            }
            for (int i = 0; i < N / 2; i++) {
                if (str[i] == str[N - i - 1]) {
                    cnt[str[i] - 'a']++;
                    move++;
                    res -= Math.min(b[i], b[N - i - 1]);
                }
            }
            for (int i = 0; i < 26; i++) {
                if (cnt[i] > move / 2) {
                    int left = cnt[i] * 2 - move;
                    List<Integer> pos = new ArrayList<>();
                    for (int j = 0; j < N / 2; j++) {
                        if (str[j] != str[N - j - 1]) {
                            if (str[N - j - 1] - 'a' == i || str[j] - 'a' == i) {
                                // do nothing
                            } else {
                                pos.add(Math.min(b[j], b[N - j - 1]));
                            }
                        }
                    }
                    Collections.sort(pos);
                    for (int j = 0; j < left && j < pos.size(); j++) {
                        res -= pos.get(j);
                    }
                }
            }
            pw.println(res);
        }
    }
}
